430          /*
   431           *      The next label is still uncompressed, so we call
   432           *      ourselves recursively in order to compress it.
   433           */
   434          if (*next < 63) {
   435                  if (!dns_label_compress(packet, start, end, &search, next, label_end)) return false;
   436
   437                  /*
   438                   *      Else it WAS compressed.
   439                   */
   440                  compressed = true;
   441          }
   442
   443          /*
   444           *      The next label wasn't compressed, OR it is invalid,
   445           *      skip it.  This check is here only to shut up the
   446           *      static analysis tools.
   447           */
   448          if (*next < 0xc0) {
   449                  return compressed;
   450          }
   451
   452          /*
   453           *      Remember where our suffix points to.
   454           */
   455          suffix = packet + ((next[0] & ~0xc0) << 8) + next[1];
   456
   457          /*
   458           *      Our label now ends with a compressed pointer.  Scan
   459           *      the input until we find either an uncompressed label
   460           *      which ends with the same compressed pointer, OR we
   461           *      find an uncompressed label which ends AT our
   462           *      compressed pointer.
   463           *
   464           *      Note that we start searching from the beginning of the
   465           *      label which resulted in us finding the compressed
   466           *      pointer!
   467           *
   468           *      We're guaranteed that any label BEFORE that one
   469           *      doesn't end with a matching compressed pointer.
   470           */
   471          q = search;
   472          while (q < end) {
   473                  if (*q == 0x00) {
   474                          q++;
   475
   476                          /*
   477                           *      None of the previous stuff matched, so
   478                           *      we tell the caller to start searching
   479                           *      from the next name.
   480                           */
   481                          search = q;
   482                          continue;
   483                  }
   484
   485                  /*
   486                   *      Skip compressed pointers.  We can't point to
   487                   *      compressed pointers.
   488                   */
   489                  if (*q > 63) {
   490                          q += 2;
   491
   492                          /*
   493                           *      None of the previous uncompressed
   494                           *      names matched, and this pointer refers
   495                           *      to a compressed name.  So it doesn't
   496                           *      match, either.
   497                           */
   498                          search = q;
   499                          continue;
   500                  }
   501
   502                  /*
   503                   *      We now have an uncompressed label in the input
   504                   *      buffer.  Check for a match.
   505                   */
   506                  ptr = q + *q + 1;
   507                  if (ptr > end) return compressed;
   508
   509                  /*
   510                   *      Label lengths aren't the same, skip it.
   511                   */
   512                  if (*q != *label) {
   513                          q = ptr;
   514                          continue;
   515                  }
   516
   517                  /*
   518                   *      If the NEXT label is uncompressed, then skip
   519                   *      it unless it's the suffix we're pointing to.
   520                   */
   521                  if (*ptr < 63) {
   522                          if (ptr != suffix) {
   523                                  q = ptr;
   524                                  continue;
   525                          }
   526
   527                          goto check_label;
   528                  }
   529
   530                  /*
   531                   *      The next label is a compressed pointer.  If
   532                   *      the compressed pointers are different, then
   533                   *      skip both this label and the compressed
   534                   *      pointer after it.
   535                   */
   536                  if ((ptr[0] != next[0]) ||
   537                      (ptr[1] != next[1])) {
   538                          q = ptr + 2;
   539
   540                          /*
   541                           *      None of the previous uncompressed
   542                           *      names matched, and this pointer refers
   543                           *      to a compressed name.  So it doesn't
   544                           *      match, either.
   545                           */
   546                          search = q;
   547                          continue;
   548                  }
   549
   550          check_label:
   551                  /*
   552                   *      Pointer is too far away.  Don't point
   553                   *      to it.
   554                   */
   555                  if ((q - packet) > (1 << 14)) return compressed;
   556
